import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.openqa.selenium.By;
import org.openqa.selenium.JavascriptExecutor;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.Select;
import org.openqa.selenium.support.ui.WebDriverWait;

import java.time.Duration;
import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;

public class Tc012TransferFundsIdeDraftTest {

    private WebDriver driver;
    private WebDriverWait wait;
    private Map<String, Object> vars;
    private JavascriptExecutor js;

    @BeforeEach
    public void setUp() {
        ChromeOptions options = new ChromeOptions();
        options.addArguments("--headless=new", "--window-size=1280,900");
        driver = new ChromeDriver(options);
        wait = new WebDriverWait(driver, Duration.ofSeconds(10));
        js = (JavascriptExecutor) driver;
        vars = new HashMap<>();
    }

    @AfterEach
    public void tearDown() {
        if (driver != null) {
            driver.quit();
        }
    }

    @Test
    public void tc012OpenSecondAccountAndTransferFunds() {
        driver.get("https://parabank.parasoft.com/parabank/register.htm");
        vars.put("uname12", js.executeScript("return 'fins4ide12_' + Math.floor(Math.random() * 900000 + 100000)"));
        wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("customer.firstName")));
        driver.findElement(By.id("customer.firstName")).sendKeys("Ivan");
        driver.findElement(By.id("customer.lastName")).sendKeys("Franchuk");
        driver.findElement(By.id("customer.address.street")).sendKeys("10 Khreshchatyk St");
        driver.findElement(By.id("customer.address.city")).sendKeys("Kyiv");
        driver.findElement(By.id("customer.address.state")).sendKeys("Kyivska");
        driver.findElement(By.id("customer.address.zipCode")).sendKeys("01001");
        driver.findElement(By.id("customer.phoneNumber")).sendKeys("380501112233");
        driver.findElement(By.id("customer.ssn")).sendKeys("1234567890");
        driver.findElement(By.id("customer.username")).sendKeys(vars.get("uname12").toString());
        driver.findElement(By.id("customer.password")).sendKeys("FinKit#2026");
        driver.findElement(By.id("repeatedPassword")).sendKeys("FinKit#2026");
        driver.findElement(By.cssSelector("input[type='submit'][value='Register']")).click();

        wait.until(ExpectedConditions.visibilityOfElementLocated(By.linkText("Open New Account")));
        driver.findElement(By.linkText("Open New Account")).click();
        wait.until(ExpectedConditions.visibilityOfElementLocated(By.cssSelector("#fromAccountId option")));
        new Select(driver.findElement(By.id("type"))).selectByVisibleText("SAVINGS");
        driver.findElement(By.cssSelector("input[type='button'][value='Open New Account']")).click();

        wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("newAccountId")));
        vars.put("acc2", driver.findElement(By.id("newAccountId")).getText());

        driver.findElement(By.linkText("Transfer Funds")).click();
        wait.until(ExpectedConditions.visibilityOfElementLocated(By.cssSelector("#toAccountId option:nth-child(2)")));
        driver.findElement(By.id("amount")).sendKeys("100.00");
        new Select(driver.findElement(By.id("toAccountId"))).selectByVisibleText(vars.get("acc2").toString());
        driver.findElement(By.cssSelector("input[type='submit'][value='Transfer']")).click();

        wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("showResult")));
        assertEquals("Transfer Complete!", driver.findElement(By.cssSelector("#showResult h1.title")).getText());
        assertEquals("$100.00", driver.findElement(By.id("amountResult")).getText());
    }
}
